import React, { useState } from 'react';
import axios from 'axios';

const BookService = () => {
  const [formData, setFormData] = useState({
    customerName: '',
    phone: '',
    email: '',
    serviceType: '',
    motorType: '',
    description: ''
  });
  const [message, setMessage] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5000/api/bookings', formData);
      setMessage('Service booked successfully! We will contact you soon.');
      setFormData({
        customerName: '',
        phone: '',
        email: '',
        serviceType: '',
        motorType: '',
        description: ''
      });
    } catch (error) {
      setMessage('Error booking service. Please try again.');
    }
  };

  return (
    <div className="container" style={{ padding: '40px 20px', maxWidth: '600px' }}>
      <h1>Book a Service</h1>
      {message && (
        <div style={{ 
          padding: '10px', 
          margin: '20px 0', 
          background: message.includes('Error') ? '#f8d7da' : '#d4edda',
          border: `1px solid ${message.includes('Error') ? '#f5c6cb' : '#c3e6cb'}`,
          borderRadius: '4px'
        }}>
          {message}
        </div>
      )}
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Customer Name *</label>
          <input
            type="text"
            name="customerName"
            value={formData.customerName}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label>Phone Number *</label>
          <input
            type="tel"
            name="phone"
            value={formData.phone}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label>Email</label>
          <input
            type="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
          />
        </div>
        <div className="form-group">
          <label>Service Type *</label>
          <select name="serviceType" value={formData.serviceType} onChange={handleChange} required>
            <option value="">Select Service</option>
            <option value="motor-winding">Motor Winding</option>
            <option value="motor-repair">Motor Repair</option>
            <option value="generator-repair">Generator Repair</option>
            <option value="other">Other</option>
          </select>
        </div>
        <div className="form-group">
          <label>Motor Type</label>
          <input
            type="text"
            name="motorType"
            value={formData.motorType}
            onChange={handleChange}
            placeholder="e.g., AC Motor, DC Motor, Single Phase"
          />
        </div>
        <div className="form-group">
          <label>Problem Description *</label>
          <textarea
            name="description"
            value={formData.description}
            onChange={handleChange}
            rows="4"
            placeholder="Describe the issue with your motor/generator"
            required
          />
        </div>
        <button type="submit" className="btn">Book Service</button>
      </form>
    </div>
  );
};

export default BookService;
